<#
CleanDub — 重复文件清理工具（单文件版）
版本: 0.3.0
仓库: https://github.com/XLcode5/CleanDub
#>

param(
    [int]$Port = 0,
    [switch]$NoBrowser,
    [switch]$SelfTest
)

$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }

$script:AppDir = $PSScriptRoot
if (-not $script:AppDir) { try { $script:AppDir = Split-Path -Parent $PSCommandPath } catch { } }
if (-not $script:AppDir) { try { $script:AppDir = Split-Path -Parent $MyInvocation.MyCommand.Path } catch { } }
if (-not $script:AppDir) { $script:AppDir = (Get-Location).ProviderPath }

# 显示启动信息
Write-Host ''
Write-Host '  ==========================================' -ForegroundColor Cyan
Write-Host '   CleanDub — 重复文件清理工具' -ForegroundColor Cyan
Write-Host '  ==========================================' -ForegroundColor Cyan
Write-Host ''
Write-Host '  版本: v0.3.0' -ForegroundColor Gray
Write-Host ''

# 检查更新（后台，不阻塞）
try {
    $resp = Invoke-RestMethod -Uri 'https://api.github.com/repos/XLcode5/CleanDub/releases/latest' -TimeoutSec 5 -ErrorAction SilentlyContinue
    $latest = $resp.tag_name -replace '^v', ''
    if ($latest -and $latest -ne '0.3.0') {
        Write-Host ('  发现新版本: v' + $latest) -ForegroundColor Yellow
        Write-Host ('  下载: ' + $resp.html_url) -ForegroundColor Gray
        Write-Host ''
    }
} catch { }

# 嵌入的资源（Base64）
$resources = @{
    'dedup_core.ps1' = @'

'@
    'dedup_server.ps1' = @'

'@
    'dedup.ps1' = @'

'@
    'dedup_ui.html' = @'

'@
    'version.json' = @'
ewogICJ2ZXJzaW9uIjogIjAuMy4wIiwKICAiYnVpbGREYXRlIjogIjIwMjYtMTAtMDIiLAogICJjaGFubmVsIjogInN0YWJsZSIsCiAgImdpdGh1YlJlcG8iOiAiWExjb2RlNS9DbGVhbkR1YiIsCiAgInVwZGF0ZUNoZWNrVXJsIjogImh0dHBzOi8vYXBpLmdpdGh1Yi5jb20vcmVwb3MvWExjb2RlNS9DbGVhbkR1Yi9yZWxlYXNlcy9sYXRlc3QiCn0=
'@
    'config.json' = @'
ewogICJkZWZhdWx0UGF0aCI6ICIiLAogICJwb3J0IjogMCwKICAib3BlbkJyb3dzZXIiOiB0cnVlLAogICJzdHJhdGVneSI6ICJDbGVhbmVzdCIsCiAgInZlcmlmeSI6ICJGdWxsIiwKICAiZGV0ZWN0TGlua3MiOiB0cnVlLAogICJleGNsdWRlRGlycyI6IFtdCn0K
'@
}

# 释放资源到临时目录
$tempRoot = Join-Path $env:TEMP ('CleanDub-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[void][System.IO.Directory]::CreateDirectory($tempRoot)

foreach ($name in $resources.Keys) {
    $path = Join-Path $tempRoot $name
    try {
        $bytes = [System.Convert]::FromBase64String($resources[$name].Trim())
        [System.IO.File]::WriteAllBytes($path, $bytes)
    } catch {
        Write-Host ('释放失败: ' + $name) -ForegroundColor Red
    }
}

# 切换到临时目录并启动服务
Push-Location $tempRoot
try {
    $serverScript = Join-Path $tempRoot 'dedup_server.ps1'
    & $serverScript -Port $Port -NoBrowser:$NoBrowser -SelfTest:$SelfTest
} finally {
    Pop-Location
}
